<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use FMonitor2\InspectionEvidence\InspectionPhotoThumbnail;
assertSameValue(true,class_exists(InspectionPhotoThumbnail::class),'INTENDED_RED A03 authenticated derivative service absent');
if(!extension_loaded('gd'))throw new TestFailure('SETUP_FAILURE: approved GD runtime is required');
$root=sys_get_temp_dir().'/fm2-thumbnail-test-'.bin2hex(random_bytes(5));mkdir($root,0700);$service=new InspectionPhotoThumbnail();
$cleanup=static function(string$p)use(&$cleanup):void{if(is_link($p)||is_file($p)){unlink($p);return;}foreach(scandir($p)?:[]as$f)if($f!=='.'&&$f!=='..')$cleanup($p.'/'.$f);rmdir($p);};
try{foreach(['jpeg','png','webp']as$format){$img=imagecreatetruecolor(1200,800);$color=imagecolorallocate($img,70,100,150);imagefill($img,0,0,$color);$file=$root.'/image.'.$format;$fn='image'.$format;$fn($img,$file);unset($img);$original=file_get_contents($file);$sha=hash('sha256',$original);$a=$service->render($file,$sha,$root.'/private');$size=getimagesizefromstring($a['bytes']);assertSameValue([640,427],[$size[0],$size[1]],'A03 proportion-preserving bounded derivative '.$format);assertSameValue([$size[0],$size[1]],[$a['width'],$a['height']],'advertised geometry matches bytes');assertSameValue($original,file_get_contents($file),'original evidence unchanged');$b=$service->render($file,$sha,$root.'/private');assertSameValue($a['bytes'],$b['bytes'],'repeat derivative bytes deterministic');assertSameValue(true,strlen($a['bytes'])<=100000,'compact derivative');}
$beforeSmall=glob($root.'/private/checklist-thumbnails/*.bin')?:[];$small=$root.'/small.png';$im=imagecreatetruecolor(32,16);imagepng($im,$small);$a=$service->render($small,hash_file('sha256',$small),$root.'/private');assertSameValue([32,16],[$a['width'],$a['height']],'no upscale');$newFiles=array_values(array_diff(glob($root.'/private/checklist-thumbnails/*.bin')?:[],$beforeSmall));assertSameValue(1,count($newFiles),'small fixture owns one derivative');file_put_contents($newFiles[0],'corrupted cache');$repaired=$service->render($small,hash_file('sha256',$small),$root.'/private');assertSameValue($a['bytes'],$repaired['bytes'],'corrupt derived cache repaired without changing original');assertSameValue($a['bytes'],file_get_contents($newFiles[0]),'repair persisted atomically for next read');
// A syntactically valid PNG header advertises an impossible decode budget; reject before GD allocation.
$huge=file_get_contents($small);$ihdr=pack('NN',50000,50000).substr($huge,24,5);$huge=substr($huge,0,16).$ihdr.pack('N',crc32('IHDR'.$ihdr)).substr($huge,33);$hugePath=$root.'/huge.png';file_put_contents($hugePath,$huge);$failed=false;try{$service->render($hugePath,hash_file('sha256',$hugePath),$root.'/private');}catch(Throwable){$failed=true;}assertSameValue(true,$failed,'oversized raster rejected before decode allocation');
$invalid=$root.'/invalid.bin';file_put_contents($invalid,'not an image');$link=$root.'/linked.png';symlink($small,$link);
foreach([[$invalid,hash_file('sha256',$invalid)],[$small,str_repeat('0',64)],[$link,hash_file('sha256',$small)]]as[$file,$sha]){$failed=false;try{$service->render($file,$sha,$root.'/private');}catch(Throwable){$failed=true;}assertSameValue(true,$failed,'bad/corrupt/symlink original rejected');}
foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/private',FilesystemIterator::SKIP_DOTS))as$f)if($f->isFile())assertSameValue(0600,$f->getPerms()&0777,'derived bytes remain private');
echo "PASS PRODUCTION-PERFORMANCE-001 A03 thumbnail\n";
}finally{$cleanup($root);}
